using UnityEngine;

namespace UI.Framework.Base
{
    public abstract class UIView : MonoBehaviour
    {
        [Header("UIView 设置")]
        [SerializeField] protected bool isInitialized = false;

        protected virtual void Awake()
        {
            Initialize();
        }

        protected virtual void Initialize()
        {
            if (isInitialized) return;
            BindComponents();
            isInitialized = true;
        }

        protected virtual void BindComponents() { }

        public virtual void Show()
        {
            gameObject.SetActive(true);
            OnShow();
        }

        public virtual void Hide()
        {
            OnHide();
            gameObject.SetActive(false);
        }

        protected virtual void OnShow() { }
        protected virtual void OnHide() { }

        protected virtual void SubscribeEvents() { }
        protected virtual void UnsubscribeEvents() { }

        protected virtual void OnEnable()
        {
            if (isInitialized)
                SubscribeEvents();
        }

        protected virtual void OnDisable()
        {
            UnsubscribeEvents();
        }

        protected T FindComponent<T>(string path = "") where T : Component
        {
            if (string.IsNullOrEmpty(path))
                return GetComponent<T>();

            Transform target = transform.Find(path);
            if (target == null)
            {
                Debug.LogWarning($"UIView: 未找到路径 {path} 下的组件 {typeof(T).Name}");
                return null;
            }
            return target.GetComponent<T>();
        }
    }
}

using System.Collections.Generic;
using System.Threading.Tasks;
using Core;
using Core.Channels;
using UI.Framework.Animation;
using UI.Framework.Manager;
using UnityEngine;

namespace UI.Framework.Base
{
  public abstract class UIScreen : MonoBehaviour
  {
    [Header("UIScreen 基础设置")]
    [SerializeField] protected string screenId;
    [SerializeField] protected UILayer defaultLayer = UILayer.Normal;
    [SerializeField] protected bool useMask = true;
    [SerializeField] protected bool closeOnEsc = true;
    [SerializeField] protected bool destroyOnClose = false;
    [SerializeField] protected UIAnimationBase openAnimation;
    [SerializeField] protected UIAnimationBase closeAnimation;

    public bool IsOpen { get; private set; }
    public bool IsAnimating { get; private set; }
    public UILayer CurrentLayer { get; private set; }
    public string ScreenId => screenId;
    public UILayer DefaultLayer => defaultLayer;
    public bool UseMask => useMask;

    protected Canvas _canvas;
    protected CanvasGroup _canvasGroup;
    protected List<MonoBehaviour> _childWidgets = new();

    protected virtual void Awake()
    {
      _canvas = GetComponent<Canvas>();
      _canvasGroup = GetComponent<CanvasGroup>();

      if (_canvasGroup == null)
        _canvasGroup = gameObject.AddComponent<CanvasGroup>();

      gameObject.SetActive(false);
      CollectChildWidgets();
    }

    protected virtual void CollectChildWidgets()
    {
      var widgets = GetComponentsInChildren<UIWidget>(true);
      foreach (var widget in widgets)
      {
        _childWidgets.Add(widget);
      }
    }

    protected virtual void Start() { }

    protected virtual void OnEnable()
    {
      SubscribeEvents();
    }

    protected virtual void OnDisable()
    {
      UnsubscribeEvents();
    }

    protected virtual void Update()
    {
      if (closeOnEsc && IsOpen && UnityEngine.Input.GetKeyDown(KeyCode.Escape))
      {
        CloseSelf();
      }
    }

    public async void Open()
    {
      if (IsOpen) return;
      IsAnimating = true;

      gameObject.SetActive(true);

      foreach (var widget in _childWidgets)
      {
        if (widget is UIWidget w)
          w.OnScreenOpened();
      }

      OnBeforeOpen();

      if (openAnimation != null)
        await openAnimation.PlayAsync(gameObject);

      IsOpen = true;
      IsAnimating = false;
      OnAfterOpen();
    }

    public async void Close()
    {
      if (!IsOpen) return;
      IsAnimating = true;

      OnBeforeClose();

      if (closeAnimation != null)
        await closeAnimation.PlayAsync(gameObject);

      IsOpen = false;
      IsAnimating = false;
      OnAfterClose();

      foreach (var widget in _childWidgets)
      {
        if (widget is UIWidget w)
          w.OnScreenClosed();
      }

      gameObject.SetActive(false);

      if (destroyOnClose)
        Destroy(gameObject);
    }

    protected virtual void OnBeforeOpen() { }
    protected virtual void OnAfterOpen() { }
    protected virtual void OnBeforeClose() { }
    protected virtual void OnAfterClose() { }

    protected virtual void SubscribeEvents() { }
    protected virtual void UnsubscribeEvents() { }

    protected T GetChannel<T>() where T : ScriptableObject
    {
      var container = EventChannelLocator.MainContainer;
      var fields = typeof(EventChannelContainerSO).GetFields();
      foreach (var field in fields)
      {
        if (field.FieldType == typeof(T))
        {
          return field.GetValue(container) as T;
        }
      }
      return null;
    }

    protected void CloseSelf() => UIManager.Instance.Close(screenId);

    public void SetLayer(UILayer layer)
    {
      CurrentLayer = layer;
      // +50 让画面排在层级 Canvas（遮罩所在）之上，同时仍然在其他层级 Canvas 之下
      if (_canvas != null)
        _canvas.sortingOrder = (int)layer * 100 + 50;
    }

    public CanvasGroup GetCanvasGroup() => _canvasGroup;
  }
}

using UI.Framework.Animation;
using UnityEngine;

namespace UI.Framework.Base
{
    public abstract class UIWidget : MonoBehaviour
    {
        [Header("UIWidget 设置")]
        [SerializeField] protected bool autoBind = true;

        [Header("UIWidget 选中动画")]
        [SerializeField] protected UIAnimationBase selectAnimation;
        [SerializeField] protected UIAnimationBase deselectAnimation;

        [Header("UIWidget 悬浮动画")]
        [SerializeField] protected UIAnimationBase hoverEnterAnimation;
        [SerializeField] protected UIAnimationBase hoverExitAnimation;

        /// <summary>当前是否处于选中状态</summary>
        public bool IsSelected { get; private set; }

        protected virtual void Awake()
        {
            if (autoBind)
                AutoBindComponents();
        }

        protected virtual void OnEnable()
        {
            SubscribeEvents();
        }

        protected virtual void OnDisable()
        {
            UnsubscribeEvents();
        }

        protected virtual void AutoBindComponents() { }

        protected virtual void SubscribeEvents() { }
        protected virtual void UnsubscribeEvents() { }

        public virtual void OnScreenOpened() { }
        public virtual void OnScreenClosed() { }

        // ──────────────────────────────────────────────
        //  选中 / 取消选中动画
        // ──────────────────────────────────────────────

        /// <summary>播放选中动画，同时将 IsSelected 设为 true</summary>
        public async void PlaySelect()
        {
            IsSelected = true;
            if (selectAnimation != null)
                await selectAnimation.PlayAsync(gameObject);
            OnSelectCompleted();
        }

        /// <summary>播放取消选中动画，同时将 IsSelected 设为 false</summary>
        public async void PlayDeselect()
        {
            IsSelected = false;
            if (deselectAnimation != null)
                await deselectAnimation.PlayAsync(gameObject);
            OnDeselectCompleted();
        }

        // ──────────────────────────────────────────────
        //  悬浮动画
        // ──────────────────────────────────────────────

        /// <summary>播放鼠标进入（悬浮）动画</summary>
        public async void PlayHoverEnter()
        {
            if (IsSelected)
                return;
            if (hoverEnterAnimation != null)
                await hoverEnterAnimation.PlayAsync(gameObject);
        }

        /// <summary>播放鼠标离开动画</summary>
        public async void PlayHoverExit()
        {
            if (IsSelected)
                return;
            if (hoverExitAnimation != null)
                await hoverExitAnimation.PlayAsync(gameObject);
        }

        // ──────────────────────────────────────────────
        //  子类可重写的回调
        // ──────────────────────────────────────────────

        /// <summary>选中动画播放完成时回调</summary>
        protected virtual void OnSelectCompleted() { }

        /// <summary>取消选中动画播放完成时回调</summary>
        protected virtual void OnDeselectCompleted() { }

        protected T FindComponent<T>(string path = "") where T : Component
        {
            if (string.IsNullOrEmpty(path))
                return GetComponent<T>();

            Transform target = transform.Find(path);
            if (target == null)
            {
                Debug.LogWarning($"UIWidget: 未找到路径 {path} 下的组件 {typeof(T).Name}");
                return null;
            }
            return target.GetComponent<T>();
        }

        protected T FindComponentInChildren<T>(bool includeInactive = false) where T : Component
        {
            return GetComponentInChildren<T>(includeInactive);
        }
    }
}

using System.Collections.Generic;
using System.Threading.Tasks;
using UI.Framework.Base;
using UI.Framework.Utils;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace UI.Framework.Manager
{
  public class UIManager : MonoBehaviour
  {
    private static UIManager _instance;
    private static bool _isQuitting;

    public static UIManager Instance
    {
      get
      {
        if (_isQuitting)
          return _instance;

        if (_instance == null)
        {
          GameObject go = new GameObject("UIManager");
          _instance = go.AddComponent<UIManager>();
          DontDestroyOnLoad(go);
          _instance.Initialize();
        }
        return _instance;
      }
    }

    private UINavigationStack _navigationStack = new();
    private Dictionary<string, UIScreen> _registeredScreens = new();
    private Dictionary<UILayer, Canvas> _layerCanvases = new();
    private Dictionary<UILayer, GameObject> _layerMasks = new();

    private const string MaskResourcePath = "UI/Mask";

    private void Awake()
    {
      if (_instance == null)
      {
        _instance = this;
        DontDestroyOnLoad(gameObject);
        Initialize();
      }
      else if (_instance != this)
      {
        Destroy(gameObject);
      }
    }

    private void Initialize()
    {
      CreateEventSystem();
      CreateLayerCanvases();
    }

    private void CreateEventSystem()
    {
      if (FindObjectOfType<EventSystem>() != null)
        return;

      GameObject esObj = new GameObject(UIConstants.EventSystemName);
      esObj.AddComponent<EventSystem>();
      esObj.AddComponent<StandaloneInputModule>();
      esObj.transform.SetParent(transform);
      Debug.Log("[UIManager] 自动创建 EventSystem");
    }

    private void CreateLayerCanvases()
    {
      foreach (UILayer layer in System.Enum.GetValues(typeof(UILayer)))
      {
        if (_layerCanvases.ContainsKey(layer))
          continue;

        GameObject canvasObj = new GameObject(layer.ToLayerName() + "Canvas");
        canvasObj.transform.SetParent(transform);

        Canvas canvas = canvasObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.ScreenSpaceOverlay;
        canvas.sortingOrder = layer.ToSortingOrder();

        // 添加 CanvasScaler 支持手机分辨率适配
        CanvasScaler scaler = canvasObj.AddComponent<CanvasScaler>();
        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
        scaler.referenceResolution = new Vector2(1920, 1080);
        scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
        scaler.matchWidthOrHeight = 0.5f;

        canvasObj.AddComponent<GraphicRaycaster>();

        _layerCanvases[layer] = canvas;
      }
    }

    private GameObject CreateMask(UILayer layer)
    {
      if (_layerMasks.TryGetValue(layer, out var existing))
        return existing;

      GameObject maskObj = new GameObject("Mask_" + layer.ToLayerName());

      Image maskImage = maskObj.AddComponent<Image>();
      maskImage.color = new Color(0, 0, 0, 0.5f);

      RectTransform rect = maskObj.GetComponent<RectTransform>();
      rect.anchorMin = Vector2.zero;
      rect.anchorMax = Vector2.one;
      rect.offsetMin = Vector2.zero;
      rect.offsetMax = Vector2.zero;

      maskObj.transform.SetParent(_layerCanvases[layer].transform);
      maskObj.transform.SetAsFirstSibling();
      maskObj.SetActive(false);

      _layerMasks[layer] = maskObj;

      return maskObj;
    }

    public void RegisterScreen(UIScreen screen)
    {
      if (string.IsNullOrEmpty(screen.ScreenId))
      {
        Debug.LogError("UIManager: 注册屏幕失败，screenId为空");
        return;
      }

      if (_registeredScreens.ContainsKey(screen.ScreenId))
      {
        Debug.LogWarning($"UIManager: 屏幕 {screen.ScreenId} 已存在，将被替换");
      }

      _registeredScreens[screen.ScreenId] = screen;
      screen.SetLayer(screen.DefaultLayer);
    }

    public void Open(string screenId)
    {
      if (!_registeredScreens.TryGetValue(screenId, out var screen))
      {
        Debug.LogError($"UIManager: 未找到屏幕 {screenId}");
        return;
      }

      Open(screen);
    }

    public void Open(UIScreen screen)
    {
      if (screen == null)
        return;

      if (_navigationStack.Contains(screen))
      {
        Debug.LogWarning($"UIManager: 屏幕 {screen.ScreenId} 已在导航栈中");
        return;
      }

      UIScreen current = _navigationStack.CurrentScreen;
      if (current != null)
      {
        current.gameObject.SetActive(false);
      }

      _navigationStack.Push(screen);

      if (screen.UseMask)
      {
        ShowMask(screen.CurrentLayer);
      }

      screen.Open();
    }

    public void Close(string screenId)
    {
      if (!_registeredScreens.TryGetValue(screenId, out var screen))
      {
        Debug.LogError($"UIManager: 未找到屏幕 {screenId}");
        return;
      }

      Close(screen);
    }

    public void Close(UIScreen screen)
    {
      if (screen == null)
        return;

      if (!_navigationStack.Contains(screen))
      {
        Debug.LogWarning($"UIManager: 屏幕 {screen.ScreenId} 不在导航栈中");
        return;
      }

      screen.Close();
      _navigationStack.Remove(screen);

      if (screen.UseMask)
      {
        HideMask(screen.CurrentLayer);
      }

      UIScreen current = _navigationStack.CurrentScreen;
      if (current != null)
      {
        current.gameObject.SetActive(true);
      }
    }

    public void CloseCurrent()
    {
      UIScreen current = _navigationStack.CurrentScreen;
      if (current != null)
      {
        Close(current);
      }
    }

    public void GoBack()
    {
      UIScreen current = _navigationStack.CurrentScreen;
      if (current != null)
      {
        Close(current);
      }
    }

    public async Task OpenAsync(string screenId)
    {
      if (!_registeredScreens.TryGetValue(screenId, out var screen))
      {
        Debug.LogError($"UIManager: 未找到屏幕 {screenId}");
        return;
      }

      await OpenAsync(screen);
    }

    public async Task OpenAsync(UIScreen screen)
    {
      if (screen == null)
        return;

      UIScreen current = _navigationStack.CurrentScreen;
      if (current != null)
      {
        current.gameObject.SetActive(false);
      }

      _navigationStack.Push(screen);

      if (screen.UseMask)
      {
        ShowMask(screen.CurrentLayer);
      }

      await Task.Run(() =>
      {
        screen.Open();
      });
    }

    public async Task CloseAsync(string screenId)
    {
      if (!_registeredScreens.TryGetValue(screenId, out var screen))
      {
        Debug.LogError($"UIManager: 未找到屏幕 {screenId}");
        return;
      }

      await CloseAsync(screen);
    }

    public async Task CloseAsync(UIScreen screen)
    {
      if (screen == null)
        return;

      await Task.Run(() =>
      {
        screen.Close();
      });

      _navigationStack.Remove(screen);

      if (screen.UseMask)
      {
        HideMask(screen.CurrentLayer);
      }

      UIScreen current = _navigationStack.CurrentScreen;
      if (current != null)
      {
        current.gameObject.SetActive(true);
      }
    }

    public void ClearAll()
    {
      foreach (var screen in _registeredScreens.Values)
      {
        if (screen != null)
        {
          screen.Close();
        }
      }

      _navigationStack.Clear();

      foreach (var mask in _layerMasks.Values)
      {
        if (mask != null)
          mask.SetActive(false);
      }
    }

    private void ShowMask(UILayer layer)
    {
      GameObject mask = CreateMask(layer);
      mask.SetActive(true);
    }

    private void HideMask(UILayer layer)
    {
      if (_layerMasks.TryGetValue(layer, out var mask))
      {
        mask.SetActive(false);
      }
    }

    public bool IsScreenOpen(string screenId)
    {
      if (_registeredScreens.TryGetValue(screenId, out var screen))
      {
        return screen.IsOpen;
      }
      return false;
    }

    public UIScreen GetScreen(string screenId)
    {
      _registeredScreens.TryGetValue(screenId, out var screen);
      return screen;
    }

    public UIScreen GetCurrentScreen()
    {
      return _navigationStack.CurrentScreen;
    }

    public T GetScreen<T>() where T : UIScreen
    {
      foreach (var screen in _registeredScreens.Values)
      {
        if (screen is T typedScreen)
          return typedScreen;
      }
      return null;
    }

    public void SetLayer(UIScreen screen, UILayer layer)
    {
      if (screen == null)
        return;

      screen.SetLayer(layer);
    }

    public void UnregisterScreen(UIScreen screen)
    {
      if (screen == null || string.IsNullOrEmpty(screen.ScreenId))
        return;

      if (_registeredScreens.TryGetValue(screen.ScreenId, out var registered) && registered == screen)
      {
        _registeredScreens.Remove(screen.ScreenId);
        _navigationStack.Remove(screen);
      }
    }

    private void OnDestroy()
    {
      if (_instance == this)
      {
        _isQuitting = true;
        _instance = null;
      }
    }
  }
}

using UnityEngine;

namespace UI.Framework
{
    public enum UILayer
    {
        Background = 0,
        Normal = 1,
        HUD = 2,
        Popup = 3,
        Top = 4,
        Loading = 5
    }

    public static class UILayerExtensions
    {
        public static int ToSortingOrder(this UILayer layer)
        {
            return (int)layer * 100;
        }

        public static string ToLayerName(this UILayer layer)
        {
            switch (layer)
            {
                case UILayer.Background: return "Background";
                case UILayer.Normal: return "Normal";
                case UILayer.HUD: return "HUD";
                case UILayer.Popup: return "Popup";
                case UILayer.Top: return "Top";
                case UILayer.Loading: return "Loading";
                default: return "Normal";
            }
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using UI.Framework.Base;

namespace UI.Framework.Manager
{
  public class UINavigationStack
  {
    private Stack<UIScreen> _screenStack = new();
    private Dictionary<UILayer, Stack<UIScreen>> _layerStacks = new();

    public UIScreen CurrentScreen => _screenStack.Count > 0 ? _screenStack.Peek() : null;
    public int Count => _screenStack.Count;

    public void Push(UIScreen screen)
    {
      _screenStack.Push(screen);

      if (!_layerStacks.ContainsKey(screen.CurrentLayer))
        _layerStacks[screen.CurrentLayer] = new Stack<UIScreen>();

      _layerStacks[screen.CurrentLayer].Push(screen);
    }

    public UIScreen Pop()
    {
      if (_screenStack.Count == 0)
        return null;

      UIScreen screen = _screenStack.Pop();

      if (_layerStacks.TryGetValue(screen.CurrentLayer, out var stack))
      {
        if (stack.Count > 0)
          stack.Pop();
      }

      return screen;
    }

    public bool Contains(string screenId)
    {
      foreach (var screen in _screenStack)
      {
        if (screen.ScreenId == screenId)
          return true;
      }
      return false;
    }

    public bool Contains(UIScreen screen)
    {
      return _screenStack.Contains(screen);
    }

    public void Remove(UIScreen screen)
    {
      _screenStack = new Stack<UIScreen>(
          new Stack<UIScreen>(_screenStack).Where(s => s != screen)
      );

      if (_layerStacks.TryGetValue(screen.CurrentLayer, out var stack))
      {
        stack = new Stack<UIScreen>(
            new Stack<UIScreen>(stack).Where(s => s != screen)
        );
        _layerStacks[screen.CurrentLayer] = stack;
      }
    }

    public void Clear()
    {
      _screenStack.Clear();

      foreach (var pair in _layerStacks)
      {
        pair.Value.Clear();
      }

      _layerStacks.Clear();
    }

    public UIScreen GetScreen(string screenId)
    {
      foreach (var screen in _screenStack)
      {
        if (screen.ScreenId == screenId)
          return screen;
      }
      return null;
    }

    public Stack<UIScreen> GetLayerStack(UILayer layer)
    {
      if (_layerStacks.TryGetValue(layer, out var stack))
        return stack;
      return new Stack<UIScreen>();
    }
  }
}

