namespace Controllers.Network
{
  public class Launcher : MonoBehaviourPunCallbacks, IObjectPoolService, IGameActionService
  {
    private bool isAutoCreate = false;
    private bool isJoiningRoom = false;
    private bool isQuittingToMenu = false;

    [SerializeField]
    public GameObject currentlySelectedCharacter;
    private Photon.Realtime.Player localPlayer;
    private InputField nameUI;
    private GameObject joinRoom;
    private GameObject TBGC;
    private GameObject joinRoomButton;
    private GameObject joinRoomInput;

    private bool isTest;

    // 拆分后的逻辑管理器
    private SpawnPointManager _spawnPointManager;
    private NetworkSceneFlow _sceneFlow;

    #region 单例模式
    public static Launcher instance;

    void Awake()
    {
      if (instance == null)
      {
        instance = this;
        DontDestroyOnLoad(gameObject);
        NetworkServiceLocator.RegisterObjectPoolService(this);
        NetworkServiceLocator.RegisterGameActionService(this);
      }
      else
      {
        Destroy(gameObject);
      }

      _sceneFlow = new NetworkSceneFlow(this);
      _spawnPointManager = new SpawnPointManager(this, currentlySelectedCharacter);

      // 只在大厅场景（场景索引1）初始化UI
      if (SceneManager.GetActiveScene().buildIndex == 1)
      {
        InitGetUI();
      }
    }
    #endregion

    void Start()
    {
      isTest = EventChannelLocator.MainContainer != null && EventChannelLocator.MainContainer.gameSettings != null && EventChannelLocator.MainContainer.gameSettings.IsTest;
      if (isTest)
        return;
      PhotonNetwork.AutomaticallySyncScene = true;
      UnityEngine.Application.runInBackground = true;
      PhotonNetwork.ConnectUsingSettings();
    }

    private void Update()
    {
      if (isTest)
        return;
      if (Input.GetKeyDown(KeyCode.Return))
      {
        ConfirmNickname();
      }
      if (Input.GetKeyDown(KeyCode.Escape))
      {
        CloseJoinRoomPanel();
      }
    }

    // ==================== 大厅 UI ====================

    public void ConfirmNickname()
    {
      if (string.IsNullOrEmpty(nameUI.text))
      {
        Debug.LogError("Name is empty");
        return;
      }
      else
      {
        PhotonNetwork.LocalPlayer.NickName = nameUI.text;
        Debug.Log($"修改昵称成功: {PhotonNetwork.LocalPlayer.NickName}");
      }
    }

    public void CloseJoinRoomPanel()
    {
      if (TBGC != null) TBGC.SetActive(false);
      if (joinRoomButton != null) joinRoomButton.SetActive(false);
      if (joinRoomInput != null) joinRoomInput.SetActive(false);
    }

    private void InitGetUI()
    {
      Debug.LogWarning("开始初始化UI组件---Launcher");
      nameUI = GameObject.Find("NameUI")?.GetComponent<InputField>();
      TBGC = GetInactiveObjectByName("TBGC");
      joinRoomButton = GetInactiveObjectByName("JoinRoomButton");
      joinRoomInput = GetInactiveObjectByName("JoinRoomInput");
      joinRoom = GameObject.Find("JoinRoom");

      // UI 初始化完成后注入 nameUI 到 SpawnPointManager
      _spawnPointManager.SetNameUI(nameUI);

      Initialize();
    }

    private void Initialize()
    {
      joinRoom
          .GetComponent<Button>()
          .onClick.AddListener(() =>
          {
            TBGC.SetActive(true);
            joinRoomButton.SetActive(true);
            joinRoomInput.SetActive(true);
          });

      joinRoomButton
          .GetComponent<Button>()
          .onClick.AddListener(() =>
          {
            string roomName = joinRoomInput.GetComponent<InputField>().text;
            if (string.IsNullOrEmpty(roomName))
            {
              Debug.LogError("Room name is empty");
              return;
            }
            {
              SwitchRoom(roomName);
            }
            CloseJoinRoomPanel();
          });

      if (TBGC != null)
      {
        Button closeBtn = TBGC.GetComponentInChildren<Button>(true);
        if (closeBtn != null && closeBtn.gameObject != joinRoomButton)
        {
          closeBtn.onClick.AddListener(CloseJoinRoomPanel);
        }
      }
    }

    public GameObject GetInactiveObjectByName(string objectName)
    {
      foreach (var root in SceneManager.GetActiveScene().GetRootGameObjects())
      {
        if (root.name == objectName && !root.activeInHierarchy)
          return root;
        var found = FindChildRecursive(root.transform, objectName);
        if (found != null) return found.gameObject;
      }
      return null;
    }

    private static Transform FindChildRecursive(Transform parent, string name)
    {
      for (int i = 0; i < parent.childCount; i++)
      {
        var child = parent.GetChild(i);
        if (child.name == name) return child;
        var result = FindChildRecursive(child, name);
        if (result != null) return result;
      }
      return null;
    }

    // ==================== 连接 & 房间管理 ====================

    private string pendingRoomName = "";

    public void SwitchRoom(string newRoomName)
    {
      if (PhotonNetwork.InRoom)
      {
        pendingRoomName = newRoomName;
        isJoiningRoom = true;
        PhotonNetwork.LeaveRoom();
        Debug.Log("正在离开当前房间...");
      }
    }

    private void SetDefaultName()
    {
      if (string.IsNullOrEmpty(PhotonNetwork.LocalPlayer.NickName))
      {
        PhotonNetwork.LocalPlayer.NickName = "玩家" + PhotonNetwork.LocalPlayer.UserId;
      }
    }

    public override void OnConnectedToMaster()
    {
      if (isTest || SceneManager.GetActiveScene().buildIndex < 1)
        return;
      base.OnConnectedToMaster();
      PhotonNetwork.AutomaticallySyncScene = true;
      Debug.Log("Connected to master");
      string roomName = "Room_" + Random.Range(1000, 9999);
      SetDefaultName();
      if (!isAutoCreate)
      {
        PhotonNetwork.CreateRoom(
            roomName,
            new Photon.Realtime.RoomOptions() { MaxPlayers = 4, PublishUserId = true },
            default
        );
        isAutoCreate = true;
      }
    }

    public override void OnCreatedRoom()
    {
      if (isTest)
        return;
      base.OnCreatedRoom();
      Debug.Log("Created room: " + PhotonNetwork.CurrentRoom.Name);
    }

    public override void OnLeftRoom()
    {
      Debug.Log("已离开房间");
      if (isQuittingToMenu)
      {
        StartCoroutine(ShowAndLoadMainMenu());
        return;
      }
      // 切换房间：离开完成后安全地加入目标房间（OnLeftRoom 时已回到 Master 服务器）
      if (isJoiningRoom && !string.IsNullOrEmpty(pendingRoomName))
      {
        Debug.Log($"正在加入房间: {pendingRoomName}");
        PhotonNetwork.JoinRoom(pendingRoomName);
        isJoiningRoom = false;
      }
    }

    /// <summary>
    /// 退出房间并返回开始界面
    /// </summary>
    public void QuitToMainMenu()
    {
      if (PhotonNetwork.InRoom)
      {
        PhotonNetwork.AutomaticallySyncScene = false;
        _spawnPointManager.ClearLocalPlayerSpawnPoint();
        isQuittingToMenu = true;
        isAutoCreate = false;
        PhotonNetwork.LeaveRoom();
        Debug.Log("正在退出房间返回主菜单...");
      }
      else
      {
        StartCoroutine(ShowAndLoadMainMenu());
      }
    }

    private IEnumerator ShowAndLoadMainMenu()
    {
      yield return StartCoroutine(Loading.Instance.Show());
      LoadMainMenuScene();
    }

    private void LoadMainMenuScene()
    {
      isQuittingToMenu = false;
      pendingRoomName = "";
      isJoiningRoom = false;
      isAutoCreate = false;
      PhotonNetwork.AutomaticallySyncScene = false;
      SceneManager.LoadScene(0);
    }

    // ==================== PUN 回调路由 ====================

    public override void OnEnable()
    {
      base.OnEnable();
      SceneManager.sceneLoaded += OnSceneLoaded;
    }

    public override void OnDisable()
    {
      base.OnDisable();
      SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    public override void OnJoinedRoom()
    {
      Debug.Log("Joined room: " + PhotonNetwork.CurrentRoom.Name);
      if (isTest)
        return;
      base.OnJoinedRoom();
      _spawnPointManager.EnsurePlayerManagerExists();
      StartCoroutine(DelayJoinRoom());
    }

    IEnumerator DelayJoinRoom()
    {
      yield return new WaitForSeconds(0.5f);
      _spawnPointManager.CreatedOrJoinedRoom();
    }

    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
      if (scene.buildIndex == 1)
      {
        var roomJoinedChannel = EventChannelLocator.MainContainer.roomJoinedChannel;
        if (roomJoinedChannel != null)
          roomJoinedChannel.Raise(new RoomJoinedEventData());
      }

      if (EventChannelLocator.MainContainer.gameSettings.IsTest)
        return;

      if (scene.buildIndex == 1)
      {
        EventChannelLocator.MainContainer.gameSettings.IsStayLobby = true;

        // 场景切换时重置暂停状态（防止卡牌面板打开时返回大厅导致 isPaused 卡在 true）
        if (Managers.GamePauseManager.isPaused)
        {
          EventChannelLocator.MainContainer.pauseChannel?.Raise(false);
        }

        InitGetUI();
        _sceneFlow.ResetForLobby();
        _sceneFlow.ResetLocalReady();

        if (PhotonNetwork.IsConnected && PhotonNetwork.InRoom)
        {
          StartCoroutine(_spawnPointManager.SpawnPlayerAfterDelay());
        }

        if (PhotonNetwork.IsConnected && !PhotonNetwork.InRoom && !isAutoCreate)
        {
          PhotonNetwork.AutomaticallySyncScene = true;
          string roomName = "Room_" + Random.Range(1000, 9999);
          SetDefaultName();
          PhotonNetwork.CreateRoom(
              roomName,
              new Photon.Realtime.RoomOptions() { MaxPlayers = 4, PublishUserId = true },
              default
          );
          isAutoCreate = true;
        }
        return;
      }

      if (scene.buildIndex > 1)
      {
        ServiceLocator.Get<GameManager>().isReady = false;
        EventChannelLocator.MainContainer.gameSettings.IsStayLobby = false;

        // 场景切换时重置暂停状态（防止卡牌面板打开时切场景导致 isPaused 卡在 true）
        if (Managers.GamePauseManager.isPaused)
        {
          EventChannelLocator.MainContainer.pauseChannel?.Raise(false);
        }

        // 进入游戏场景时重置流程标志（非 MasterClient 的 isRoomLoading/isLoadingScene 不会被 LoadLevel 隐式重置）
        _sceneFlow.ResetForLobby();

        Hashtable loadProps = new Hashtable
            {
                { PlayerPropertyKeys.Level, true },
                { PlayerPropertyKeys.Loaded, true },
                { PlayerPropertyKeys.PlayerName, PhotonNetwork.LocalPlayer.NickName },
            };

        PhotonNetwork.LocalPlayer.SetCustomProperties(loadProps);
        Debug.Log(
            $"[Launcher] 本地玩家场景加载完成，设置 PlayerLoaded=true: {PhotonNetwork.LocalPlayer.NickName}"
        );

        _spawnPointManager.CreatedOrJoinedRoom();
      }
    }

    public override void OnPlayerLeftRoom(Photon.Realtime.Player otherPlayer)
    {
      _spawnPointManager.HandlePlayerLeftRoom(otherPlayer);
    }

    public override void OnPlayerPropertiesUpdate(
        Photon.Realtime.Player targetPlayer,
        Hashtable changedProps
    )
    {
      if (changedProps.ContainsKey(PlayerPropertyKeys.Level))
      {
        Debug.Log(
            $"玩家 {targetPlayer.NickName} 的 PlayerLevel 属性已更新: {changedProps[PlayerPropertyKeys.Level]}"
        );
      }

      if (changedProps.ContainsKey(PlayerPropertyKeys.Ready))
      {
        _sceneFlow.CheckAllPlayersReady();
      }

      if (changedProps.ContainsKey(PlayerPropertyKeys.Loaded))
      {
        _sceneFlow.CheckAllPlayersLoaded();
      }

      if (changedProps.ContainsKey(PlayerPropertyKeys.SpawnPoint))
      {
        object spawnPointValue = changedProps[PlayerPropertyKeys.SpawnPoint];
        Debug.Log($"玩家 {targetPlayer.NickName} 的生成点更新: {spawnPointValue}");
      }
    }

    void OnDestroy()
    {
      _spawnPointManager.HandleDestroy();
    }

    // ==================== 接口门面（IGameActionService / IObjectPoolService） ====================

    // IGameActionService
    public void SetLocalReady(bool ready) => _sceneFlow.SetLocalReady(ready);

    // IObjectPoolService
    public void ReturnToLobby() => _sceneFlow.ReturnToLobby();

    // CharactorPanel 直接调用
    public void SwitchCharacter(string newCharacterName) => _spawnPointManager.SwitchCharacter(newCharacterName);
  }
}

using System;
using System.Collections.Generic;
using UnityEngine;

namespace Managers
{
    public static class ServiceLocator
    {
        private static Dictionary<Type, object> _services = new();

        public static void Register<T>(T service) where T : class
        {
            _services[typeof(T)] = service;
        }

        public static void Unregister<T>() where T : class
        {
            _services.Remove(typeof(T));
        }

        public static T Get<T>() where T : class
        {
            if (_services.TryGetValue(typeof(T), out var service))
                return service as T;
            Debug.LogError($"Service {typeof(T)} not registered");
            return null;
        }

        public static bool TryGet<T>(out T service) where T : class
        {
            if (_services.TryGetValue(typeof(T), out var s))
            {
                service = s as T;
                return true;
            }
            service = null;
            return false;
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

namespace Controllers.Services
{
    /// <summary>
    /// Domain 层服务注册器
    /// 用途：替代 Application.ServiceLocator，使 Domain 层不依赖 Application 层
    /// 
    /// 使用方式：
    /// - 在 Application/Infrastructure 层的 Awake/Start 中 Register 实现
    /// - Domain 层内部通过 Get/TryGet 获取服务
    /// </summary>
    public static class DomainServiceLocator
    {
        private static Dictionary<Type, object> _services = new Dictionary<Type, object>();

        public static void Register<T>(T service) where T : class
        {
            var type = typeof(T);
            _services[type] = service;
        }

        public static void Unregister<T>() where T : class
        {
            _services.Remove(typeof(T));
        }

        public static T Get<T>() where T : class
        {
            if (_services.TryGetValue(typeof(T), out var service))
                return service as T;
            return null;
        }

        public static bool TryGet<T>(out T service) where T : class
        {
            if (_services.TryGetValue(typeof(T), out var s))
            {
                service = s as T;
                return true;
            }
            service = null;
            return false;
        }
    }
}

using System.Collections.Generic;
using Core;
using Controllers.Rune;
using UI.Framework;
using UI.Framework.Base;
using UI.Framework.Manager;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using UI.Framework.Animation;

public class ShopPanel : UIScreen
{
  [Header("商店符文列表（与符文面板一致）")]
  [SerializeField] private GameObject runeSlotPrefab;
  [SerializeField] private Transform runeSlotContainer;

  [Header("详情信息（只显示名字、描述、价格）")]
  [SerializeField] private GameObject detailPanel;
  [SerializeField] private TextMeshProUGUI detailName;
  [SerializeField] private TextMeshProUGUI detailDescription;
  [SerializeField] private TextMeshProUGUI detailPrice;
  [SerializeField] private Button purchaseButton;

  [Header("金币显示")]
  [SerializeField] private TextMeshProUGUI coinText;

  [SerializeField] private ShopRuneDatabaseSO shopDatabase;

  private List<GameObject> shopRuneSlots = new List<GameObject>();
  private ShopRuneConfigSO selectedRune;
  private RuneSlot selectedRuneSlot;
  private bool isListenerInitialized;

  protected override void Awake()
  {
    screenId = "ShopPanel";
    base.Awake();
    UIManager.Instance.RegisterScreen(this);
  }

  protected override void Start()
  {
    base.Start();
    ResolveDetailReferences();
    InitializeShop();
  }

  protected override void OnBeforeOpen()
  {
    base.OnBeforeOpen();
    EnsureListenerInitialized();
    UpdateCoinDisplay();
    RefreshShopItems();
  }

  protected override void OnAfterClose()
  {
    base.OnAfterClose();
    ClearSelection();
  }

  private void ResolveDetailReferences()
  {
    if (detailName == null)
      detailName = FindChildTMP("DetailName");
    if (detailDescription == null)
      detailDescription = FindChildTMP("DetailDescription");
    if (detailPrice == null)
      detailPrice = FindChildTMP("DetailPrice");
    if (purchaseButton == null)
      purchaseButton = GetComponentInChildren<Button>(true);
  }

  private TextMeshProUGUI FindChildTMP(string name)
  {
    var child = transform.Find(name);
    return child != null ? child.GetComponent<TextMeshProUGUI>() : null;
  }

  private void EnsureListenerInitialized()
  {
    if (isListenerInitialized) return;
    isListenerInitialized = true;

    if (purchaseButton != null)
    {
      purchaseButton.onClick.AddListener(OnPurchaseClicked);
      if (purchaseButton.GetComponent<ButtonFloatAnim>() == null)
        purchaseButton.gameObject.AddComponent<ButtonFloatAnim>();
    }

    var coinChannel = EventChannelLocator.MainContainer?.coinUpdateChannel;
    if (coinChannel != null)
    {
      coinChannel.OnEventRaised += OnCoinUpdated;
    }
  }

  private void InitializeShop()
  {
    EnsureListenerInitialized();

    if (detailPanel != null)
    {
      detailPanel.SetActive(false);
    }
  }

  private void OnCoinUpdated(CoinUpdateData data)
  {
    UpdateCoinDisplay();
  }

  private void RefreshShopItems()
  {
    // 刷新列表时旧 slot 会被销毁，清空选中引用
    selectedRuneSlot = null;

    foreach (var slot in shopRuneSlots)
    {
      Destroy(slot);
    }
    shopRuneSlots.Clear();

    if (shopDatabase == null)
    {
      Debug.LogError("[ShopPanel] shopDatabase 未赋值");
      return;
    }

    if (runeSlotPrefab == null || runeSlotContainer == null)
    {
      Debug.LogError("[ShopPanel] runeSlotPrefab 或 runeSlotContainer 未赋值");
      return;
    }

    foreach (var runeConfig in shopDatabase.shopRunes)
    {
      GameObject slotObj = Instantiate(runeSlotPrefab, runeSlotContainer);
      ShopRuneSlot shopSlot = slotObj.AddComponent<ShopRuneSlot>();

      RuneSlot runeSlot = slotObj.GetComponent<RuneSlot>();
      if (runeSlot != null)
      {
        shopSlot.Initialize(runeSlot, runeConfig, OnRuneSelected);
      }

      shopRuneSlots.Add(slotObj);
    }
  }

  private void UpdateCoinDisplay()
  {
    if (coinText != null)
    {
      int coins = Managers.CoinManager.Instance.GetCoins();
      coinText.text = $"金币: {FormatCoins(coins)}";
    }
  }

  private static string FormatCoins(int amount)
  {
    if (amount < 1000)
      return amount.ToString();
    if (amount < 1000000)
      return (amount / 1000f).ToString("0.#") + "K";
    return (amount / 1000000f).ToString("0.#") + "M";
  }

  private void OnRuneSelected(ShopRuneConfigSO runeConfig, RuneSlot runeSlot)
  {
    // 取消上一个选中项的背景图
    if (selectedRuneSlot != null && selectedRuneSlot != runeSlot)
    {
      selectedRuneSlot.PlayDeselect();
    }

    // 选中当前项，切换背景图
    selectedRuneSlot = runeSlot;
    if (runeSlot != null && !runeSlot.IsSelected)
    {
      runeSlot.PlaySelect();
    }

    selectedRune = runeConfig;

    // 显示详情面板
    if (detailPanel != null)
    {
      detailPanel.SetActive(true);
    }

    // 更新详情文本（不依赖 detailPanel 是否赋值）
    if (detailName != null)
      detailName.text = runeConfig.runeName;
    if (detailDescription != null)
      detailDescription.text = runeConfig.description;
    if (detailPrice != null)
      detailPrice.text = $"{runeConfig.price} ";

    UpdatePurchaseButtonState();

    // 使用RuneInfoChannel展示详情信息，与RunePanel保持一致
    if (runeConfig.runeData != null)
    {
      var runePowers = new Dictionary<int, string>();
      if (runeConfig.runeData.powers != null)
      {
        foreach (var power in runeConfig.runeData.powers)
        {
          runePowers[power.value] = power.label;
        }
      }

      var args = new Core.RuneEquipArgs(
          runeConfig.runeId,
          runeConfig.runeData.runeName,
          runePowers,
          runeConfig.runeData.specialPowerName,
          runeConfig.runeData.specialPowerDescription
      );
      EventChannelLocator.MainContainer.runeInfoChannel.Raise(args);
    }
  }

  private void OnPurchaseClicked()
  {
    if (selectedRune == null)
    {
      Debug.LogWarning("[ShopPanel] 购买失败：未选中符文");
      return;
    }

    Debug.Log($"[ShopPanel] 点击购买，runeId={selectedRune.runeId}, price={selectedRune.price}, allowRepeat={selectedRune.allowRepeatPurchase}");
    bool success = Managers.ShopManager.Instance.PurchaseRune(selectedRune.runeId);
    Debug.Log($"[ShopPanel] 购买结果: {success}");

    if (success)
    {
      RefreshShopItems();
      UpdatePurchaseButtonState();
    }
  }

  private void UpdatePurchaseButtonState()
  {
    if (purchaseButton == null || selectedRune == null) return;

    bool isAvailable = Managers.ShopManager.Instance.IsRuneAvailable(selectedRune.runeId);
    bool hasPurchased = !selectedRune.allowRepeatPurchase && RuneInventory.HasRune(selectedRune.runeId);
    int currentCoins = Managers.CoinManager.Instance.GetCoins();
    bool canAfford = currentCoins >= selectedRune.price;

    purchaseButton.interactable = isAvailable && !hasPurchased && canAfford;

    var btnText = purchaseButton.GetComponentInChildren<TextMeshProUGUI>();
    if (btnText != null)
    {
      btnText.text = hasPurchased ? "已购买" : (purchaseButton.interactable ? "购买" : "不可购买");
    }
  }

  private void ClearSelection()
  {
    if (selectedRuneSlot != null && selectedRuneSlot.IsSelected)
    {
      selectedRuneSlot.PlayDeselect();
    }
    selectedRuneSlot = null;
    selectedRune = null;

    if (detailPanel != null)
    {
      detailPanel.SetActive(false);
    }
  }

  void OnDestroy()
  {
    var coinChannel = EventChannelLocator.MainContainer?.coinUpdateChannel;
    if (coinChannel != null)
    {
      coinChannel.OnEventRaised -= OnCoinUpdated;
    }
  }
}

using System.Collections;
using Managers;
using DG.Tweening;
using TMPro;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace UI.Framework.Panel
{
    /// <summary>
    /// Loading 面板 — 完全独立的 UI 单例，不继承 UIScreen。
    /// 遵循项目标准单例模式（与 UIManager / PlayerManager 相同）。
    /// </summary>
    public class Loading : MonoBehaviour
    {
        private CanvasGroup _canvasGroup;
        private Coroutine _bounceRoutine;
        private Tween _iconPopTween;
        private Sequence _iconRotateSeq;

        [Header("子对象引用")]
        [SerializeField] private Image icon;
        [SerializeField] private TextMeshProUGUI loadingText;

        // TMP 逐字弹跳用
        private Vector3[][] _charBaseVertices;
        private int[] _charMeshIndex;
        private int[] _charVertexIndex;
        private int _charCount;

        #region 单例模式
        public static Loading instance;
        public static Loading Instance => instance;

        void Awake()
        {
            if (instance == null)
            {
                instance = this;
                DontDestroyOnLoad(gameObject);
            }
            else
            {
                Destroy(gameObject);
            }
            Initialize();
        }
        #endregion


        private void Initialize()
        {
            var canvas = gameObject.GetComponent<Canvas>();
            if (canvas == null)
                canvas = gameObject.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            canvas.sortingOrder = 9999;

            // 添加 CanvasScaler 支持手机分辨率适配
            var scaler = gameObject.GetComponent<CanvasScaler>();
            if (scaler == null)
                scaler = gameObject.AddComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920, 1080);
            scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
            scaler.matchWidthOrHeight = 0.5f;

            if (gameObject.GetComponent<GraphicRaycaster>() == null)
                gameObject.AddComponent<GraphicRaycaster>();

            _canvasGroup = gameObject.GetComponent<CanvasGroup>();
            if (_canvasGroup == null)
                _canvasGroup = gameObject.AddComponent<CanvasGroup>();
            _canvasGroup.alpha = 0f;
            _canvasGroup.blocksRaycasts = false;

            // icon 恢复为初始状态
            if (icon != null)
            {
                icon.transform.localScale = Vector3.zero;
                icon.transform.localEulerAngles = Vector3.zero;
            }
        }

        private void OnEnable()
        {
            SceneManager.sceneLoaded += OnSceneLoaded;
        }

        private void OnDisable()
        {
            SceneManager.sceneLoaded -= OnSceneLoaded;
        }

        private void OnDestroy()
        {
            KillIconTweens();
            StopBounceAnimation();

            if (instance == this)
            {
                SceneManager.sceneLoaded -= OnSceneLoaded;
                instance = null;
            }
        }

        #region Icon 开场动画

        /// <summary>
        /// icon 蹦出来 + 分段旋转（4 周期 × 90°，每周期间隔 0.5s）
        /// </summary>
        private void PlayIconOpen()
        {
            if (icon == null) return;

            KillIconTweens();

            // 重置：从完全透明、零尺寸、无旋转开始
            icon.transform.localScale = Vector3.zero;
            icon.transform.localEulerAngles = Vector3.zero;
            icon.color = new Color(icon.color.r, icon.color.g, icon.color.b, 0f);

            // ★★★ 震撼开场：急速淡入 + 大 overshoot 弹出 ★★★
            //     scale 冲到 1.25 再弹回 1.0，配合 OutBack overshoot:4 制造"炸出"感
            Sequence openSeq = DOTween.Sequence();
            openSeq
                .Join(icon.DOFade(1f, 0.08f))                                    // 瞬间显形
                .Join(icon.transform.DOScale(1.25f, 0.2f).SetEase(Ease.OutBack, overshoot: 4f)) // 炸出
                .Append(icon.transform.DOScale(1f, 0.15f).SetEase(Ease.OutQuad));               // 回落

            _iconPopTween = openSeq;

            // 开场结束后才开始循环旋转
            openSeq.OnComplete(() =>
            {
                if (this == null) return;
                _iconRotateSeq = DOTween.Sequence();
                for (int i = 0; i < 4; i++)
                {
                    _iconRotateSeq
                        .AppendInterval(0.5f)
                        .Append(
                            icon.transform
                                .DOBlendableRotateBy(new Vector3(0f, 0f, 90f), 0.25f)
                                .SetEase(Ease.OutQuad)
                        );
                }
                _iconRotateSeq.SetLoops(-1, LoopType.Restart);
                _iconRotateSeq.Play();
            });
        }

        private void KillIconTweens()
        {
            if (_iconPopTween != null && _iconPopTween.IsActive())
                _iconPopTween.Kill();
            _iconPopTween = null;

            if (_iconRotateSeq != null && _iconRotateSeq.IsActive())
                _iconRotateSeq.Kill();
            _iconRotateSeq = null;
        }

        #endregion

        #region "加载中"逐字弹跳

        private void CacheCharVertices()
        {
            if (loadingText == null) return;

            // ★★★ 必须强制刷新 Canvas 布局，textInfo 才会正确生成 ★★★
            Canvas.ForceUpdateCanvases();
            loadingText.ForceMeshUpdate();

            var info = loadingText.textInfo;
            if (info == null) return;

            _charCount = Mathf.Min(3, info.characterCount);
            if (_charCount == 0) return;

            _charBaseVertices = new Vector3[_charCount][];
            _charMeshIndex = new int[_charCount];
            _charVertexIndex = new int[_charCount];

            for (int i = 0; i < _charCount; i++)
            {
                var ch = info.characterInfo[i];
                if (!ch.isVisible) continue;

                _charMeshIndex[i] = ch.materialReferenceIndex;
                _charVertexIndex[i] = ch.vertexIndex;

                var verts = info.meshInfo[_charMeshIndex[i]].vertices;
                _charBaseVertices[i] = new Vector3[4];
                System.Array.Copy(verts, _charVertexIndex[i], _charBaseVertices[i], 0, 4);
            }
        }

        private void StartBounceAnimation()
        {
            StopBounceAnimation();
            CacheCharVertices();
            if (_charCount == 0) return;

            _bounceRoutine = StartCoroutine(BounceRoutine());
        }

        private void StopBounceAnimation()
        {
            if (_bounceRoutine != null)
            {
                StopCoroutine(_bounceRoutine);
                _bounceRoutine = null;
            }

            if (loadingText != null && _charBaseVertices != null)
            {
                loadingText.ForceMeshUpdate();
                var info = loadingText.textInfo;
                for (int i = 0; i < _charCount; i++)
                {
                    if (_charBaseVertices[i] == null) continue;
                    int m = _charMeshIndex[i];
                    int vi = _charVertexIndex[i];
                    for (int j = 0; j < 4; j++)
                        info.meshInfo[m].vertices[vi + j] = _charBaseVertices[i][j];
                }
                loadingText.UpdateVertexData();
            }
        }

        private IEnumerator BounceRoutine()
        {
            float bounceHeight = 12f;
            float cycleTime = 0.5f;
            float stagger = 0.18f;

            while (true)
            {
                float elapsed = Time.time;

                for (int i = 0; i < _charCount; i++)
                {
                    if (_charBaseVertices[i] == null) continue;

                    float t = Mathf.Repeat(elapsed / cycleTime + i * (stagger / cycleTime), 1f);

                    float offset;
                    if (t < 0.35f)
                    {
                        float p = t / 0.35f;
                        offset = bounceHeight * (1f - (1f - p) * (1f - p));
                    }
                    else
                    {
                        float p = (t - 0.35f) / 0.65f;
                        offset = bounceHeight * (1f - p) * (1f - p);
                    }

                    var info = loadingText.textInfo;
                    int mi = _charMeshIndex[i];
                    int vi = _charVertexIndex[i];
                    for (int j = 0; j < 4; j++)
                    {
                        info.meshInfo[mi].vertices[vi + j].y = _charBaseVertices[i][j].y + offset;
                    }
                }

                loadingText.UpdateVertexData();
                yield return null;
            }
        }

        #endregion

        #region 场景切换回调

        private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
        {
            Debug.Log($"[Loading] OnSceneLoaded 触发，场景: {scene.name}");
            StartCoroutine(HideWithMinDisplay());
        }

        private IEnumerator HideWithMinDisplay()
        {
            // 延迟 1s，场景已切换成功，但 loading 动画继续播放
            yield return new WaitForSeconds(1f);
            yield return StartCoroutine(Hide());
        }

        #endregion

        #region 公开接口

        public IEnumerator Show()
        {
            _canvasGroup.blocksRaycasts = true;

            // ★★★ icon 蹦出 + 旋转 ★★★
            PlayIconOpen();

            // ★★★ "加载中"逐字弹跳 ★★★
            StartBounceAnimation();

            // 协程淡入
            float elapsed = 0f;
            float duration = 0.2f;
            while (elapsed < duration)
            {
                elapsed += Time.deltaTime;
                _canvasGroup.alpha = elapsed / duration;
                yield return null;
            }
            _canvasGroup.alpha = 1f;

            yield return new WaitForSeconds(1f);
        }

        public IEnumerator Hide()
        {
            _canvasGroup.alpha = 0.5f;
            _canvasGroup.blocksRaycasts = true;

            // 停止所有持续动画
            KillIconTweens();
            StopBounceAnimation();

            // ★★★ 关闭动画：icon 转圈缩小 → 文字缩小 → 整体淡出 ★★★
            float duration = 0.4f;

            // 1) Icon: 高速自转 360° + 缩小到 0 + 渐隐
            if (icon != null)
            {
                icon.transform
                    .DOBlendableRotateBy(new Vector3(0f, 0f, 360f), duration * 0.55f)
                    .SetEase(Ease.InCubic)
                    .Play();
                icon.transform
                    .DOScale(0f, duration)
                    .SetEase(Ease.InBack)
                    .Play();
                icon
                    .DOFade(0f, duration * 0.6f)
                    .Play();
            }

            // 2) 文字: 延迟 0.15s 后缩小到 0
            if (loadingText != null)
            {
                loadingText.transform
                    .DOScale(0f, duration * 0.45f)
                    .SetDelay(0.15f)
                    .SetEase(Ease.InBack)
                    .Play();
            }

            // 3) Canvas 淡出
            float elapsed = 0f;
            while (elapsed < duration)
            {
                elapsed += Time.deltaTime;
                _canvasGroup.alpha = 1f - Mathf.Clamp01(elapsed / duration);
                yield return null;
            }

            // 收尾：确保所有元素复位到隐藏状态
            if (icon != null)
            {
                icon.transform.localScale = Vector3.zero;
                icon.transform.localEulerAngles = Vector3.zero;
                icon.color = new Color(icon.color.r, icon.color.g, icon.color.b, 0f);
            }
            if (loadingText != null)
                loadingText.transform.localScale = Vector3.one;

            _canvasGroup.blocksRaycasts = false;
            _canvasGroup.alpha = 0f;

            yield return new WaitForSeconds(1f);

            // 1) 对局结算（有实际数据时才发放金币并弹结算面板）
            if (MatchStatisticsManager.Instance != null)
            {
                MatchStatisticsManager.Instance.FinalizeMatch();
            }

            // 2) 广播当前金币数，初始化金币 UI 显示
            if (CoinManager.Instance != null)
            {
                CoinManager.Instance.BroadcastCurrentCoins();
            }
        }

        #endregion
    }
}

