        [PunRPC]
        public void RPC_SyncSetTime(float time)
        {
            SyncedGameTimeManager.HandleSyncSetTime(time);
        }

        [PunRPC]
        public void RPC_SyncStartTime()
        {
            SyncedGameTimeManager.HandleSyncStartTime();
        }

        [PunRPC]
        public void RPC_SyncPauseTime()
        {
            SyncedGameTimeManager.HandleSyncPauseTime();
        }

        [PunRPC]
        public void RPC_SyncResetTime()
        {
            SyncedGameTimeManager.HandleSyncResetTime();
        }

        [PunRPC]
        public void RPC_BossSpawn(string bossName)
        {
            SyncedGameTimeManager.HandleBossSpawn(bossName);
        }

        // ============================================================
        // PlayerController RPC
        // ============================================================

        [PunRPC]
        public void NoticeOtherPlayerDamage(string playerId, float maxHP, float currentHP)
        {
            if (EventChannelLocator.MainContainer?.healthUpdateChannel != null)
            {
                EventChannelLocator.MainContainer.healthUpdateChannel.Raise(
                    HealthUpdateData.OtherPlayer(playerId, maxHP, currentHP));
            }
        }

        [PunRPC]
        public void RPC_SyncPlayerElement(int actorNumber, int elementInt)
        {
            PlayerController.HandleSyncPlayerElement(actorNumber, elementInt);
        }

        // ============================================================
        // WizardBoy RPC
        // ============================================================

        [PunRPC]
        public void RPC_InitElementPool(int viewID, int elementInt)
        {
            var go = NetworkServiceLocator.ObjectService.FindByViewID(viewID);
            if (go != null)
            {
                var wizardBoy = go.GetComponent<WizardBoy>();
                if (wizardBoy != null)
                {
                    wizardBoy.HandleInitElementPool(elementInt);
                }
            }
        }

        // ============================================================
        // Boss_Horror (SpiderBoss) RPC
        // ============================================================

        [PunRPC]
        public void RPC_SyncPlayerTarget(int targetViewID)
        {
            var boss = GetSpiderBoss();
            if (boss != null)
            {
                boss.HandleSyncPlayerTarget(targetViewID);
            }
        }

        [PunRPC]
        public void RPC_SyncTriggerAnim(string animName)
        {
            var boss = GetSpiderBoss();
            if (boss != null)
            {
                boss.HandleSyncTriggerAnim(animName);
            }
        }

        // ============================================================
        // Ball Robot_Blue RPC
        // ============================================================

        [PunRPC]
        public void RPC_PlayTriggerAnimation(int viewID, string triggerName)
        {
            var go = NetworkServiceLocator.ObjectService.FindByViewID(viewID);
            if (go != null)
            {
                var ball = go.GetComponent<BallRobot_Blue>();
                if (ball != null)
                {
                    ball.HandlePlayTriggerAnimation(triggerName);
                }
            }
        }

        [PunRPC]
        public void RPC_OnPushed(int viewID, Vector3 pushDir, float moveDist)
        {
            var go = NetworkServiceLocator.ObjectService.FindByViewID(viewID);
            if (go != null)
            {
                var ball = go.GetComponent<BallRobot_Blue>();
                if (ball != null)
                {
                    ball.HandleOnPushed(pushDir, moveDist);
                }
            }
        }

        [PunRPC]
        public void RPC_StartTransfer(int viewID)
        {
            var go = NetworkServiceLocator.ObjectService.FindByViewID(viewID);
            if (go != null)
            {
                var ball = go.GetComponent<BallRobot_Blue>();
                if (ball != null)
                {
                    ball.HandleStartTransfer();
                }
            }
        }

        // ============================================================
        // IDomainRpcService 实现（供 Domain 层通过接口调用，消除直接依赖）
        // ============================================================

        /// <summary>
        /// RPC：非房主端请求房主销毁指定怪物（处理房主端未检测到死亡的情况）
        /// </summary>
        [PunRPC]
        public void RPC_RequestEnemyDestroy(int viewID)
        {
            var go = NetworkServiceLocator.ObjectService.FindByViewID(viewID);
            if (go != null)
            {
                PhotonNetwork.Destroy(go);
            }
        }

        /// <summary>
        /// 通过此 Bridge 的 PhotonView 发送 RPC 到指定目标
        /// </summary>
        public void InvokeRPC(string methodName, NetworkTarget target, params object[] parameters)
        {
            if (photonView == null)
            {
                Debug.LogWarning($"[DomainRpcBridge] photonView is null, cannot send RPC {methodName}");
                return;
            }
            photonView.RPC(methodName, NetworkTargetMapper.ToRpcTarget(target), parameters);
        }
    }
}

using UnityEngine;
using System;

namespace Core.Channels.Base
{
    public abstract class BaseEventChannelSO : ScriptableObject
    {
        [SerializeField] private bool enableDebugLog;
        public event Action OnEventRaised;

        public virtual void Raise()
        {
            if (enableDebugLog)
                Debug.Log($"[Event] {name} raised");

            if (OnEventRaised == null) return;
            foreach (Delegate listener in OnEventRaised.GetInvocationList())
            {
                try
                {
                    ((Action)listener)?.Invoke();
                }
                catch (Exception e)
                {
                    Debug.LogError($"[Event] {name} listener error: {e.Message}\n{e.StackTrace}");
                }
            }
        }

        public void RegisterListener(Action listener) => OnEventRaised += listener;
        public void UnregisterListener(Action listener) => OnEventRaised -= listener;
    }

    public abstract class BaseEventChannelSO<T> : ScriptableObject
    {
        [SerializeField] private bool enableDebugLog;
        public event Action<T> OnEventRaised;

        public virtual void Raise(T value)
        {
            if (enableDebugLog)
                Debug.Log($"[Event] {name} raised: {value}");

            if (OnEventRaised == null) return;
            foreach (Delegate listener in OnEventRaised.GetInvocationList())
            {
                try
                {
                    ((Action<T>)listener)?.Invoke(value);
                }
                catch (Exception e)
                {
                    Debug.LogError($"[Event] {name} listener error: {e.Message}\n{e.StackTrace}");
                }
            }
        }

        public void RegisterListener(Action<T> listener) => OnEventRaised += listener;
        public void UnregisterListener(Action<T> listener) => OnEventRaised -= listener;
    }

    public abstract class BaseEventChannelSO<T1, T2> : ScriptableObject
    {
        [SerializeField] private bool enableDebugLog;
        public event Action<T1, T2> OnEventRaised;

        public virtual void Raise(T1 value1, T2 value2)
        {
            if (enableDebugLog)
                Debug.Log($"[Event] {name} raised: ({value1}, {value2})");

            if (OnEventRaised == null) return;
            foreach (Delegate listener in OnEventRaised.GetInvocationList())
            {
                try
                {
                    ((Action<T1, T2>)listener)?.Invoke(value1, value2);
                }
                catch (Exception e)
                {
                    Debug.LogError($"[Event] {name} listener error: {e.Message}\n{e.StackTrace}");
                }
            }
        }

        public void RegisterListener(Action<T1, T2> listener) => OnEventRaised += listener;
        public void UnregisterListener(Action<T1, T2> listener) => OnEventRaised -= listener;
    }
}

using Controllers.Services;
using UnityEngine;

namespace Controllers.Network
{
    /// <summary>
    /// 早期游戏服务注册器
    /// 用途：在 Launcher 场景对象加载之前，先注册 ObjectPoolService 和 GameActionService
    /// 这样 LobbyCanvas 等组件在 Start() 中就能直接使用这些服务
    /// 
    /// Launcher 的 Awake() 会覆盖本注册器注册的服务实例，因此
    /// 在 Launcher 加载后，实际调用会直接走 Launcher 自身的方法
    /// </summary>
    public static class GameServiceRegistrar
    {
        private static bool _isRegistered = false;

        /// <summary>
        /// 注册早期的轻量级服务实现
        /// 由 InfrastructureRegistrar 在游戏启动时调用
        /// </summary>
        public static void EnsureRegistered()
        {
            if (_isRegistered)
                return;
            _isRegistered = true;

            NetworkServiceLocator.RegisterObjectPoolService(new EarlyObjectPoolService());
            NetworkServiceLocator.RegisterGameActionService(new EarlyGameActionService());

            Debug.Log("[GameServiceRegistrar] 初始服务注册完成（Launcher 加载后会被覆盖）");
        }

        /// <summary>
        /// 轻量级 IObjectPoolService 实现
        /// GetInactiveObjectByName — 自包含实现，不依赖 Launcher
        /// ReturnToLobby — 委托给 Launcher.instance（此时 Launcher 通常已加载）
        /// </summary>
        private class EarlyObjectPoolService : IObjectPoolService
        {
            public GameObject GetInactiveObjectByName(string objectName)
            {
                var allObjects = Resources.FindObjectsOfTypeAll<GameObject>();
                return System.Array.Find(
                    allObjects,
                    obj =>
                        obj != null
                        && obj.name == objectName
                        && !obj.activeInHierarchy
                        && obj.scene.IsValid()
                );
            }

            public void ReturnToLobby()
            {
                if (Launcher.instance != null)
                {
                    Launcher.instance.ReturnToLobby();
                }
                else
                {
                    Debug.LogWarning("[EarlyObjectPoolService] Launcher 尚未加载，无法返回大厅");
                }
            }
        }

        /// <summary>
        /// 轻量级 IGameActionService 实现
        /// 所有操作委托给 Launcher.instance
        /// </summary>
        private class EarlyGameActionService : IGameActionService
        {
            public void QuitToMainMenu()
            {
                if (Launcher.instance != null)
                {
                    Launcher.instance.QuitToMainMenu();
                }
                else
                {
                    Debug.LogWarning("[EarlyGameActionService] Launcher 尚未加载，无法退出到主菜单");
                }
            }

            public void SetLocalReady(bool ready)
            {
                if (Launcher.instance != null)
                {
                    Launcher.instance.SetLocalReady(ready);
                }
                else
                {
                    Debug.LogWarning("[EarlyGameActionService] Launcher 尚未加载，无法设置准备状态");
                }
            }
        }
    }
}

